From da61ab95bece4c5c6e2791817956d07738657c72 Mon Sep 17 00:00:00 2001
From: Derek Bruening <bruening@google.com>
Date: Tue, 5 Jan 2016 10:27:55 -0500
Subject: [PATCH] i#556: fix compile error in 3db7e90

Fixes VS2010 build breakage from 3db7e90.

Review-URL: https://codereview.appspot.com/282950043

diff --git a/core/lib/instrument.c b/core/lib/instrument.c
index a0ba9708e..da533e5ec 100644
--- a/core/lib/instrument.c
+++ b/core/lib/instrument.c
@@ -1,5 +1,5 @@
 /* ******************************************************************************
- * Copyright (c) 2010-2015 Google, Inc.  All rights reserved.
+ * Copyright (c) 2010-2016 Google, Inc.  All rights reserved.
  * Copyright (c) 2010-2011 Massachusetts Institute of Technology  All rights reserved.
  * Copyright (c) 2002-2010 VMware, Inc.  All rights reserved.
  * ******************************************************************************/
@@ -4255,9 +4255,10 @@ DR_API
 bool
 dr_using_console(void)
 {
-    FILE_FS_DEVICE_INFORMATION DeviceInformation;
-    HANDLE herr = get_stderr_handle();
+    bool res;
     if (get_os_version() >= WINDOWS_VERSION_8) {
+        FILE_FS_DEVICE_INFORMATION device_info;
+        HANDLE herr = get_stderr_handle();
         /* The handle is invalid iff it's a gui app and the parent is a console */
         if (herr == INVALID_HANDLE_VALUE) {
             module_data_t *app_kernel32 = dr_lookup_module_by_name("kernel32.dll");
@@ -4268,9 +4269,9 @@ dr_using_console(void)
             dr_free_module_data(app_kernel32);
             herr = get_stderr_handle();
         }
-        if (nt_query_volume_info(herr, &DeviceInformation, sizeof(DeviceInformation),
+        if (nt_query_volume_info(herr, &device_info, sizeof(device_info),
                                  FileFsDeviceInformation) == STATUS_SUCCESS) {
-            if (DeviceInformation.DeviceType == FILE_DEVICE_CONSOLE)
+            if (device_info.DeviceType == FILE_DEVICE_CONSOLE)
                 return true;
         }
         return false;
@@ -4278,7 +4279,7 @@ dr_using_console(void)
     /* We detect cmd window using what kernel32!WriteFile uses: a handle
      * having certain bits set.
      */
-    bool res = (((ptr_int_t)get_stderr_handle() & 0x10000003) == 0x3);
+    res = (((ptr_int_t)get_stderr_handle() & 0x10000003) == 0x3);
     CLIENT_ASSERT(!res || get_os_version() < WINDOWS_VERSION_8,
                   "Please report this: Windows 8 does have old-style consoles!");
     return res;
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by a compile error in the `dr_using_console` function due to the use of an undeclared variable `DeviceInformation` and improper handling of variable declarations, which led to confusion and potential misuse of the variable. The changes made in the patch addressed these issues by renaming the variable for consistency and moving its declaration to a more appropriate location in the code.

        Commit message:
        i#556: fix compile error in 3db7e90

Fixes VS2010 build breakage from 3db7e90.

Review-URL: https://codereview.appspot.com/282950043  

        Patch:
         /* ******************************************************************************
- * Copyright (c) 2010-2015 Google, Inc.  All rights reserved.
+ * Copyright (c) 2010-2016 Google, Inc.  All rights reserved.
  * Copyright (c) 2010-2011 Massachusetts Institute of Technology  All rights reserved.
  * Copyright (c) 2002-2010 VMware, Inc.  All rights reserved.

 DR_API
 bool
 dr_using_console(void)
 {
-    FILE_FS_DEVICE_INFORMATION DeviceInformation;
-    HANDLE herr = get_stderr_handle();
+    bool res;
     if (get_os_version() >= WINDOWS_VERSION_8) {
+        FILE_FS_DEVICE_INFORMATION device_info;
+        HANDLE herr = get_stderr_handle();
         /* The handle is invalid iff it's a gui app and the parent is a console */
         if (herr == INVALID_HANDLE_VALUE) {
             module_data_t *app_kernel32 = dr_lookup_module_by_name("kernel32.dll");
             if (privload_attach_parent_console(app_kernel32->start) == false) {
                 dr_free_module_data(app_kernel32);
                 return false;
             }
             dr_free_module_data(app_kernel32);
             herr = get_stderr_handle();
         }
-        if (nt_query_volume_info(herr, &DeviceInformation, sizeof(DeviceInformation),
+        if (nt_query_volume_info(herr, &device_info, sizeof(device_info),
                                  FileFsDeviceInformation) == STATUS_SUCCESS) {
-            if (DeviceInformation.DeviceType == FILE_DEVICE_CONSOLE)
+            if (device_info.DeviceType == FILE_DEVICE_CONSOLE)
                 return true;
         }
         return false;
     }
     /* We detect cmd window using what kernel32!WriteFile uses: a handle
      * having certain bits set.
      */
-    bool res = (((ptr_int_t)get_stderr_handle() & 0x10000003) == 0x3);
+    res = (((ptr_int_t)get_stderr_handle() & 0x10000003) == 0x3);
     CLIENT_ASSERT(!res || get_os_version() < WINDOWS_VERSION_8,
                   "Please report this: Windows 8 does have old-style consoles!");
     return res;
 }



